#!/usr/bin/env pwsh\n<#\n.SYNOPSIS\n    RAG Application Full Stack Startup Script\n    Starts Ollama, FastAPI backend, and Node.js frontend in sequence\n\n.DESCRIPTION\n    This script automates the startup of the complete RAG application stack.\n    It runs each service in a new terminal window for easy monitoring.\n\n.PARAMETER SkipOllama\n    Skip starting Ollama (use if already running)\n\n.PARAMETER Port\n    Frontend port (default: 3010)\n\n.EXAMPLE\n    .\\startup.ps1\n    .\\startup.ps1 -SkipOllama\n    .\\startup.ps1 -Port 8080\n#>\n\nparam(\n    [switch]$SkipOllama,\n    [int]$Port = 3010\n)\n\n$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path\ncd $scriptDir\n\nWrite-Host \"🚀 RAG Application Full Stack Startup\" -ForegroundColor Cyan\nWrite-Host \"=====================================\"\nWrite-Host \"\"\n\n# Check if Python venv exists\nif (-not (Test-Path \".venv\\Scripts\\Activate.ps1\")) {\n    Write-Host \"❌ Python virtual environment not found at .venv\" -ForegroundColor Red\n    Write-Host \"Please run: python -m venv .venv\" -ForegroundColor Yellow\n    Write-Host \"Then: .venv\\Scripts\\Activate.ps1\" -ForegroundColor Yellow\n    exit 1\n}\n\n# Activate venv\nWrite-Host \"✓ Activating Python virtual environment...\" -ForegroundColor Green\n& \".venv\\Scripts\\Activate.ps1\"\n\n# Check if Ollama CLI exists\n$ollamaPath = $null\nif (Get-Command ollama -ErrorAction SilentlyContinue) {\n    $ollamaPath = (Get-Command ollama).Source\n    Write-Host \"✓ Ollama found at: $ollamaPath\" -ForegroundColor Green\n} else {\n    Write-Host \"⚠ Ollama CLI not found in PATH\" -ForegroundColor Yellow\n    Write-Host \"   Install from: https://ollama.ai\" -ForegroundColor Yellow\n    if (-not $SkipOllama) {\n        Write-Host \"   Continuing anyway - you'll need to start Ollama manually\" -ForegroundColor Yellow\n    }\n}\n\nWrite-Host \"\"\n\n# Start Ollama\nif (-not $SkipOllama -and $ollamaPath) {\n    Write-Host \"📦 Starting Ollama service...\" -ForegroundColor Cyan\n    Write-Host \"   (A new window will open - keep it running)\" -ForegroundColor Gray\n    \n    try {\n        Start-Process -FilePath \"pwsh\" -ArgumentList \"-NoExit\", \"-Command\", \"ollama serve\" -PassThru | Out-Null\n        Start-Sleep -Seconds 3\n        Write-Host \"✓ Ollama service started (http://localhost:11434)\" -ForegroundColor Green\n    } catch {\n        Write-Host \"❌ Failed to start Ollama: $_\" -ForegroundColor Red\n    }\n    \n    Write-Host \"\"\n}\n\n# Start FastAPI\nWrite-Host \"🔧 Starting FastAPI backend...\" -ForegroundColor Cyan\nWrite-Host \"   (A new window will open - keep it running)\" -ForegroundColor Gray\nWrite-Host \"   Backend will be at: http://127.0.0.1:8000\" -ForegroundColor Gray\n\ntry {\n    $fastapiCmd = \"cd '$scriptDir'; uvicorn app:app --reload --host 127.0.0.1 --port 8000\"\n    Start-Process -FilePath \"pwsh\" -ArgumentList \"-NoExit\", \"-Command\", $fastapiCmd -PassThru | Out-Null\n    Start-Sleep -Seconds 3\n    Write-Host \"✓ FastAPI backend started (http://127.0.0.1:8000)\" -ForegroundColor Green\n} catch {\n    Write-Host \"❌ Failed to start FastAPI: $_\" -ForegroundColor Red\n    exit 1\n}\n\nWrite-Host \"\"\n\n# Start Node.js Frontend\nWrite-Host \"🌐 Starting Node.js frontend server...\" -ForegroundColor Cyan\nWrite-Host \"   (A new window will open)\" -ForegroundColor Gray\nWrite-Host \"   Frontend will be at: http://localhost:$Port\" -ForegroundColor Gray\n\ntry {\n    $env:PORT = $Port\n    $nodeCmd = \"cd '$scriptDir'; node server.js\"\n    Start-Process -FilePath \"pwsh\" -ArgumentList \"-NoExit\", \"-Command\", $nodeCmd -PassThru | Out-Null\n    Start-Sleep -Seconds 2\n    Write-Host \"✓ Node.js frontend started (http://localhost:$Port)\" -ForegroundColor Green\n} catch {\n    Write-Host \"❌ Failed to start Node.js: $_\" -ForegroundColor Red\n    exit 1\n}\n\nWrite-Host \"\"\nWrite-Host \"====================================\" -ForegroundColor Green\nWrite-Host \"✅ RAG Application Stack Started!\" -ForegroundColor Green\nWrite-Host \"====================================\" -ForegroundColor Green\nWrite-Host \"\"\nWrite-Host \"📍 Access the application at:\" -ForegroundColor Cyan\nWrite-Host \"   🌐 Frontend:  http://localhost:$Port\" -ForegroundColor White\nWrite-Host \"   🔧 FastAPI:   http://127.0.0.1:8000\" -ForegroundColor White\nWrite-Host \"   📚 API Docs:  http://127.0.0.1:8000/docs\" -ForegroundColor White\nWrite-Host \"   🔗 Ollama:    http://127.0.0.1:11434\" -ForegroundColor White\nWrite-Host \"\"\nWrite-Host \"⏳ Services are starting. If you see connection errors, wait a moment and refresh.\" -ForegroundColor Yellow\nWrite-Host \"\"\nWrite-Host \"🛑 To stop all services: Close each terminal window\" -ForegroundColor Gray\nWrite-Host \"\"\nWrite-Host \"📖 For detailed setup info, see: STARTUP_GUIDE.md\" -ForegroundColor Gray\n\nWrite-Host \"\"\nWrite-Host \"Opening browser...\" -ForegroundColor Cyan\nStart-Process \"http://localhost:$Port\"\n\nWrite-Host \"\"\nWrite-Host \"This window can now be closed. Services will continue running.\" -ForegroundColor Gray\n"